contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 val) public payable {
        // Drive c through the public entry Initialized.
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Since Initialized() just completed, SetMinSum must now revert for any val.
        bool reverted;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        // General rule: after the deciding call Initialized(), the contract is initialized,
        // so any later SetMinSum call must revert regardless of the provided value.
        assert(reverted);
    }
}

